import json
from datetime import datetime
from pathlib import Path

from mock_api import TRACE, search
from query_audit import build_rejection
from timezone_defaults import DEFAULT_TIMEZONE
from window_projection import utc_pair, wall_clock_pair


def _parse_bound(payload, param):
    """Parse one bound and report a field-level error without aborting the batch."""
    try:
        value = payload[param]
        if not isinstance(value, str):
            raise TypeError("value must be a string")
        # Python 3.10 does not accept the ISO-8601 ``Z`` spelling directly.
        parsed = datetime.fromisoformat(value[:-1] + "+00:00" if value.endswith("Z") else value)
    except (KeyError, TypeError, ValueError) as exc:
        return None, build_rejection(
            param,
            f"must be a valid ISO 8601 datetime ({exc})",
            payload,
        )

    was_naive = parsed.tzinfo is None
    if was_naive:
        parsed = parsed.replace(tzinfo=DEFAULT_TIMEZONE)
    return (parsed, was_naive), None


def _normalized_payload(start, end, start_naive, end_naive):
    return {
        "start_utc": start.astimezone(DEFAULT_TIMEZONE).isoformat(),
        "end_utc": end.astimezone(DEFAULT_TIMEZONE).isoformat(),
        "default_timezone": "UTC",
        "start_was_naive": start_naive,
        "end_was_naive": end_naive,
    }


def validate_range(payload):
    errors = []
    start_result, start_error = _parse_bound(payload, "start_date")
    if start_error:
        errors.append(start_error)

    end_result = None
    if "end_date" in payload:
        end_result, end_error = _parse_bound(payload, "end_date")
        if end_error:
            errors.append(end_error)

    if errors or end_result is None:
        return errors

    start, start_naive = start_result
    end, end_naive = end_result
    start_utc, end_utc = utc_pair({"start": start, "end": end})
    normalized = _normalized_payload(start, end, start_naive, end_naive)

    if end_utc < start_utc:
        errors.append(
            build_rejection(
                "date_range",
                "end must be greater than or equal to start after UTC normalization",
                payload,
                normalized,
            )
        )

    start_local, end_local = wall_clock_pair({"start": start, "end": end})
    different_offsets = start.utcoffset() != end.utcoffset()
    repeated_hour = (
        start_local.date() == end_local.date()
        and start_local.hour == end_local.hour
    )
    if different_offsets and repeated_hour and end_local < start_local:
        errors.append(
            build_rejection(
                "date_range",
                "ambiguous fall-back DST range: end wall-clock time is earlier than start",
                payload,
                normalized,
            )
        )
    return errors


def process_queries(path):
    TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    accepted = []
    rejected = []
    for index, query in enumerate(payload):
        errors = validate_range(query)
        if errors:
            rejected.append({"index": index, "errors": errors, "original": query})
            continue
        accepted.append(search(query))
    return {"accepted": accepted, "rejected": rejected, "trace": list(TRACE)}

